  add('terrain','standard','日本の海に面していない県は、全部でいくつありますか（栃木・群馬・埼玉・山梨・長野・岐阜・滋賀・奈良）。',8,[4,6,10],['海のない県を内陸県といいます。','関東地方と中部地方近畿地方にあります。'],'海に面していない県は、栃木県・群馬県・埼玉県・山梨県・長野県・岐阜県・滋賀県・奈良県の8県です。');

  add('terrain','standard','東北地方の中央を南北に走り東北地方を日本海側と太平洋側に分けている山脈は、どれですか。','奥羽山脈',['飛騨山脈','赤石山脈','越後山脈'],['東北地方の「背骨」のような山脈です。','「奥」と「羽」の字が使われています。'],'奥羽山脈は東北地方の中央を南北に走り日本海側と太平洋側を分けています。', {"kind":"japanMap","bounds":[138,36.6,142.7,41.5],"marks":[],"areas":[],"routes":[{"type":"ridge","points":[[140.83,40.65],[140.75,39.9],[140.73,39.2],[140.5,38.6],[140.12,37.5]]}],"lakes":[],"caption":"位置をたしかめるための略地図。地名や数字は示していない","study":true});
  add('terrain','advanced','日本付近にはいくつのプレート（地球の表面をおおうかたい岩の板）が集まっていますか。',4,[2,3,5],['太平洋プレート・フィリピン海プレート・北アメリカプレート・ユーラシアプレートです。','プレートの境目では地震や火山の活動が多くなります。'],'日本付近には4つのプレートがぶつかりあっていて、地震や火山が多く見られます。');
  add('terrain','advanced','日本に地震や火山が多い理由は、何ですか。','プレートの境目に位置しているから',['緯度が低いから','海が近いから','大きな川が多いから'],['プレートが動くと、ゆれが起こります。','日本付近のプレートの数を思い出しましょう。'],'日本はプレートの境目に位置していて、プレートの動きによる地震や火山の活動が多くなります。');
  add('terrain','advanced','日本でいちばん長い信濃川は、長野県ではなんとよばれますか。','千曲川',['利根川','木曽川','天竜川'],['新潟県に入ると、名前が変わります。','川の名前が県によってかわる川です。'],'信濃川は長野県では千曲川とよばれ新潟県に入ると信濃川の名前になります。', {"kind":"japanMap","bounds":[135,34,140.5,38.8],"marks":[],"areas":[],"routes":[{"type":"river","points":[[138.72,35.9],[138.45,36.2],[138.25,36.6],[138.35,36.95],[138.75,37.3],[138.9,37.65],[139.04,37.94]]}],"lakes":[],"caption":"位置をたしかめるための略地図。地名や数字は示していない","study":true});
  add('terrain','advanced','日本の川が短くて流れが急になる理由として、ただしいものはどれですか。','国土がせまく山が海に近いから',['山が少ないから','雨がふらないから','平野が広いから'],['川は山から海へ流れます。','山と海の距離を考えましょう。'],'国土がせまく山が海に近いので、日本の川は短くて流れが急になります。');
  add('terrain','advanced','扇状地が果樹園（ももやぶどうなど）に向いているのは、なぜですか。','水はけがよいから',['水もちがよいから','土がとてもやわらかいから','雪が多いから'],['石や砂がまじった地面です。','水がたまりにくい土地です。'],'扇状地は石や砂が多く水はけがよいので、ももやぶどうなどの果樹栽培にむいています。');
  add('terrain','advanced','三角州にひろがる平地が人々の住む場所として、利用されてきたのはなぜですか。','土地が平らで水が得やすいから',['高い山があるから','雪が積もるから','火山が近いから'],['土や砂が積もった平らな土地です。','川の水が近くにあります。'],'三角州は平らで水が得やすいため、田や町として、利用されてきました。');
  add('terrain','advanced','琵琶湖から流れ出し大阪湾にそそぐ川は何ですか。','淀川',['利根川','信濃川','木曽川'],['京都や大阪を流れる川です。','京都では宇治川とよばれます。'],'琵琶湖から流れ出る川は、淀川（瀬田川・宇治川）となり大阪湾にそそぎます。', {"kind":"japanMap","bounds":[134.7,33.9,137.1,35.9],"marks":[],"areas":[],"routes":[{"type":"river","points":[[135.9193,34.9953],[135.91,34.94],[135.86,34.91],[135.79,34.89],[135.68,34.87],[135.59,34.77],[135.44,34.68]]}],"lakes":[[[136.220978,35.385037],[136.248942,35.376795],[136.278673,35.364726],[136.276613,35.336761],[136.252769,35.28407],[136.239817,35.270823],[136.163282,35.225786],[136.104998,35.205475],[136.077917,35.190462],[136.060255,35.164558],[136.078506,35.158671],[136.073796,35.149251],[136.056428,35.14042],[136.036411,35.136593],[136.018455,35.135416],[135.99991,35.131884],[135.983132,35.125408],[135.970768,35.115988],[135.964587,35.123347],[135.957227,35.103625],[135.953106,35.078309],[135.945159,35.056821],[135.926614,35.047695],[135.919255,35.038865],[135.919255,34.995299],[135.909541,34.978814],[135.898355,34.979992],[135.884814,34.990294],[135.873334,35.005896],[135.86833,35.023558],[135.873628,35.038865],[135.921609,35.105096],[135.928085,35.119226],[135.932207,35.171328],[135.936916,35.186341],[135.957227,35.219015],[136.016395,35.266702],[136.026109,35.2773],[136.034057,35.292312],[136.067908,35.307619],[136.074384,35.321454],[136.042887,35.386509],[136.043182,35.397694],[136.051424,35.410941],[136.058489,35.43655],[136.070852,35.454212],[136.09499,35.444204],[136.113535,35.476584],[136.122366,35.486592],[136.126487,35.47158],[136.128253,35.455684],[136.134729,35.443321],[136.152685,35.438022],[136.157395,35.445381],[136.160339,35.462455],[136.163282,35.499544],[136.177706,35.495129],[136.189775,35.486887],[136.19684,35.474818],[136.197429,35.458628],[136.197429,35.465987],[136.1989,35.435079],[136.205376,35.406231],[136.220978,35.385037]]],"caption":"位置をたしかめるための略地図。地名や数字は示していない","study":true});
  add('terrain','advanced','日本アルプスのうちいちばん北にある山脈は、どれですか。','飛騨山脈',['木曽山脈','赤石山脈','奥羽山脈'],['北アルプスともよばれます。','槍ヶ岳や穂高岳があります。'],'日本アルプスは北から飛騨山脈（北アルプス）・木曽山脈（中央アルプス）・赤石山脈（南アルプス）です。', {"kind":"japanMap","bounds":[135,34,140.5,38.8],"marks":[],"areas":[],"routes":[{"type":"ridge","points":[[137.65,36.7],[137.6,36.1],[137.65,35.65]]},{"type":"ridge","points":[[137.85,36],[137.75,35.65],[137.8,35.3]]},{"type":"ridge","points":[[138.2,35.8],[138.15,35.4],[138.1,35.05]]}],"lakes":[],"caption":"位置をたしかめるための略地図。地名や数字は示していない","study":true});
  add('terrain','advanced','鳥取県に広がる風が運んだ砂が積もってできた日本最大級の砂の丘を何といいますか。','鳥取砂丘',['九十九里浜','天橋立','三保の松原'],['日本海側にある観光地です。','砂の丘がつづく場所です。'],'鳥取県の日本海側には、風が運んだ砂が積もってできた鳥取砂丘が広がっています。',{kind:'image', src:'img/diagrams/soc5_terrain_033.webp', alt:'海ぞいに風でできた砂の丘があり、砂の風紋が見える絵', caption:'海ぞいの砂の丘', study:true});
  add('terrain','advanced','火山の噴火でできた大きなくぼ地（カルデラ）をもち熊本県にある火山はどれですか。','阿蘇山',['桜島','浅間山','雲仙岳'],['世界でも大きなカルデラがあります。','火口のまわりに牧場や町があります。'],'熊本県の阿蘇山には世界でも大きなカルデラがありそのなかに町や田畑があります。',{kind:'image', src:'img/diagrams/soc5_terrain_034.webp', alt:'大きな火口のくぼ地の中に町と田畑があり、まわりを山がかこむ絵', caption:'火口のくぼ地の中の町', study:true});
  add('terrain','advanced','火山のある土地が人々にもたらしてくれるめぐみは、どれですか。','温泉',['地震','洪水','津波'],['観光やくらしに利用されます。','別府や草津が有名です。'],'火山のある土地には温泉などのめぐみがあり観光に利用されます。');
  add('terrain','advanced','国土の約4分の3が山地で人々が住んでいるのは、おもにどんなところですか。','平野や盆地',['高い山の頂上','海の上','砂漠'],['平らな土地が暮らしやすいです。','日本の人口の多くは平野に集中しています。'],'山地が多い日本では人々はおもに平野や盆地に集まって住んでいます。');

  // ---- 国土の気候：基礎9・標準15・発展12 ----
  add('climate','basic','季節によってふく向きがかわる風を何といいますか。','季節風（モンスーン）',['偏西風','貿易風','台風'],['夏と冬で風の向きが反対になります。','日本の気候に大きなえいきょうをあたえます。'],'季節によって向きがかわる風を季節風（モンスーン）といい日本の気候に大きく関わります。');
  add('climate','basic','日本の夏の季節風はどの方向からふきますか。','南東',['北西','北東','南西'],['太平洋のほうからあたたかくしめった風がふきます。','夏は南の海から風がふいてきます。'],'夏は太平洋から南東の季節風がふき太平洋側に雨を多くふらせます。');
  add('climate','basic','日本の冬の季節風はどの方向からふきますか。','北西',['南東','南西','北東'],['ユーラシア大陸のほうからつめたい風がふきます。','日本海側に雪をふらせます。'],'冬は大陸から北西の季節風がふき日本海側に雪や雨を多くふらせます。');
  add('climate','basic','日本の気候のおもな特ちょうは、どれですか。','春・夏・秋・冬の四季がある',['一年中雨がふらない','一年中夏のように暑い','一年中雪がふる'],['日本は温帯にあります。','季節ごとに気温や天気が変わります。'],'日本の大部分は温帯にあり春夏秋冬の四季があります。');
  add('climate','basic','6月から7月ごろくもりや雨の日が続く時期を何といいますか。','梅雨（つゆ）',['台風','秋雨','夕立'],['北海道ではほとんど見られません。','田植えのころの雨の多い時期です。'],'6月から7月ごろにくもりや雨の日が続く時期を梅雨といい田畑に水をもたらします。');
  add('climate','basic','夏から秋にかけて、日本に近づき大雨や強い風をもたらす熱帯の海で生まれる低気圧を何といいますか。','台風',['梅雨前線','季節風','こがらし'],['日本の南の海で生まれます。','8月・9月に多くやってきます。'],'台風は熱帯の海で発生した低気圧が発達したもので、強い風と大雨をもたらします。');
  add('climate','basic','冬に雪がたくさんふるのは、日本のどちら側ですか。','日本海側',['太平洋側','瀬戸内','どちらも同じ'],['冬の季節風は日本海をわたってきます。','新潟県や秋田県などが、あてはまります。'],'冬の北西の季節風が日本海をわたるときにしめった空気になり日本海側に雪を多くふらせます。');
  add('climate','basic','夏に雨が多く冬に晴れの日が多い（かわいている）のは、日本のどちら側ですか。','太平洋側',['日本海側','北海道だけ','内陸だけ'],['夏の季節風は南東からふきます。','冬は山をこえてかわいた風がふいてきます。'],'太平洋側は夏に雨が多く冬は山をこえた乾燥した風がふくので、晴れの日が多くなります。');
  add('climate','basic','日本の暖かさ・寒さが、北から南でちがう理由として、ただしいものはどれですか。','南北に長く緯度の差が大きいから',['土地が平らだから','島がたくさんあるから','火山が多いから'],['北海道と沖縄を比べてみましょう。','緯度が低いほど気温は高くなります。'],'日本は南北に長いので、北と南で気温が大きくちがいます。');

