  add('climate','advanced','夏に南東の季節風がふくとき、雨が多くなるのは日本のどちら側ですか。','太平洋側',['日本海側','どちらも同じ','北海道だけ'],['風は太平洋からふきます。','山にぶつかって雨雲になります。'],'夏の南東の季節風は太平洋側の山にぶつかって、雨を多くふらせます。');
  add('climate','advanced','冬に日本海側で雪が多く太平洋側で雪が少ないのは、なぜですか。','季節風が山をこえるときに雪をふらせかわいた風になるから',['太平洋側のほうが寒いから','日本海側は海がこおるから','太平洋側には山がないから'],['風は日本海をわたってきます。','山をこえた後は水蒸気が少なくなります。'],'日本海側で水蒸気をふくんだ風が山にぶつかって雪を降らせ山をこえた後はかわいた風になるため、太平洋側は晴れが多くなります。');
  add('climate','advanced','南西諸島で昔から屋根の瓦をしっくいで固めたり家のまわりに石垣をめぐらせたりするのは、何から家を守るためですか。','台風の強い風',['雪','地震','火山灰'],['強い風がふく地いきです。','家がふき飛ばされないための工夫です。'],'沖縄などでは台風の強い風から家を守るため、屋根の瓦をしっくいで固め石垣を築いてきました。',{kind:'image', src:'img/diagrams/soc5_landlife_020.webp', alt:'赤いかわら屋根と石垣、屋根の上のシーサーがある伝統的な家の絵', caption:'赤いかわらと石垣の家', study:true});
  add('climate','advanced','北海道に梅雨がほとんどないのは、なぜですか。','梅雨前線が北海道まで北上しないことが多いから',['雨がふらない土地だから','雪が一年中ふるから','台風が来ないから'],['梅雨前線は本州の南にかかります。','前線のいちが関係しています。'],'梅雨前線は北海道の南でおとろえることが多く北海道では梅雨がほとんどありません。');
  add('climate','advanced','ある都市の年間降水量が約1000mmで冬の気温は0度近く夏と冬の気温の差が大きい。この都市は日本のどの地域に近いですか。','中央高地',['南西諸島','日本海側','瀬戸内'],['標高が高い内陸の気候です。','雨は少なめです。'],'夏と冬の気温差が大きく雨が少ないのは中央高地の気候の特ちょうです。');
  add('climate','advanced','冬に日本海側の地いきで雪のたいさく（雪おろし・流雪溝など）が必要になるのは、なぜですか。','雪がたくさんふり積もるから',['雨がまったくふらないから','夏がとても暑いから','台風がたくさん来るから'],['冬の季節風と関係があります。','積もった雪は生活のじゃまになります。'],'雪が多くふる日本海側では、雪おろしや融雪などのたいさくが、くらしに必要になります。');
  add('climate','advanced','台風が日本の南の海で発達しやすいのは、なぜですか。','海水の温度が高く水蒸気が多く出るから',['海水の温度が低いから','陸地に近いから','風がふかないから'],['台風は熱帯の海で生まれます。','あたたかい海のエネルギーを使います。'],'台風は海水の温度が高い熱帯の海で水蒸気がたくさん出ることで発達します。');
  add('climate','advanced','台風が通りすぎたあとにおこることがある災害として、あてはまるものはどれですか。','川のこう水や土砂くずれ',['火山の噴火','津波','地割れ'],['雨がたくさんふったあとです。','山の斜面や川のようすに注意しましょう。'],'台風による大雨のあと川のこう水や土砂くずれが、起こることがあります。');
  add('climate','advanced','台風が近づいてきたとき、気象情報を確認するのに役立つのはどれですか。','台風情報（進路予想図）',['ハザードマップだけ','新聞の広告','料理の本'],['台風の進路や強さを予想して、まとめた情報です。','テレビやインターネットで見られます。'],'台風の進路予想図などの気象情報を確認して、早めに備えることが大切です。');
  add('climate','advanced','日本の気候をつくる要因として、「季節風」のほかにえいきょうが大きいものはどれですか。','海流（暖流・寒流）',['火山','川','砂漠'],['日本のまわりを流れる海水の流れです。','黒潮や親潮のことです。'],'日本のまわりを流れる暖流・寒流も気候に大きくえいきょうします。');
  add('climate','advanced','夏の太平洋側で雨が多くなるある地域の「降水量」とは、何の量のことですか。','雨や雪がふった量',['雲の量','風の強さ','温度'],['mm（ミリメートル）で表します。','雨量計ではかります。'],'降水量は雨や雪がふった量を水に直して、mmで表したものです。');
  add('climate','advanced','日本の気候が地域ごとにちがうおもな理由として、ただしいものはどれですか。','季節風・地形・海流・緯度などのえいきょうをうけるから',['どの地いきも同じだから','気温だけで決まるから','風がふかないから'],['日本は南北に長く山が多いです。','いくつかの条件が組み合わさっています。'],'日本の気候は緯度・季節風・地形・海流などのえいきょうで地いきごとにちがいが生まれます。');

  // ---- 地形・気候とくらし：基礎9・標準15・発展12 ----
  add('landlife','basic','岐阜県の海津市など川にかこまれた低い土地で水害をふせぐためにまわりを堤防でかこんだ地いきを何といいますか。','輪中',['盆地','扇状地','三角州'],['木曽川・長良川・揖斐川の下流にあります。','「輪」の字が使われています。'],'まわりを堤防でかこんだ地いきを輪中といい水害からくらしを守ってきました。',{kind:'image', src:'img/diagrams/soc5_landlife_001.webp', alt:'川に囲まれた低い土地を、堤防でぐるりと囲んだ集落と田畑を上から見た絵', caption:'堤防で囲んだ低い土地', study:true});
  add('landlife','basic','輪中がつくられた木曽川・長良川・揖斐川をまとめて何といいますか。','木曽三川',['利根三川','信濃三川','富士三川'],['三つの川がならんで流れています。','愛知県・岐阜県・三重県にまたがります。'],'木曽川・長良川・揖斐川をまとめて木曽三川といいます。');
  add('landlife','basic','輪中の人々が水害にそなえて家の土台を高くしたり高いところにつくったりした食料や舟などを置いておく建物を何といいますか。','水屋',['蔵だけ','納屋だけ','母屋'],['水がきたときにそなえる建物です。','高い石垣の上につくられました。'],'水屋は水害にそなえて食料や舟などをたくわえておく高いところにつくられた建物です。',{kind:'image', src:'img/diagrams/soc5_landlife_003.webp', alt:'川ぞいの農家で、高い石垣の上に小さな倉のような建物があり、軒下に小舟がある絵', caption:'石垣の上の倉と軒下の小舟', study:true});
  add('landlife','basic','標高が高く夏でもすずしい気候をいかしてつくられている野菜を何といいますか。','高原野菜',['冬野菜','ハウス野菜','促成野菜'],['キャベツ・レタス・はくさいなどです。','群馬県や長野県の高原でさかんです。'],'標高の高い土地のすずしい気候をいかしてつくる野菜を高原野菜といいます。',{kind:'image', src:'img/diagrams/soc5_landlife_004.webp', alt:'夏の高原に広がるキャベツ畑とレタス畑、遠くに山がある絵', caption:'高原の野菜畑', study:true});
  add('landlife','basic','夏でもすずしい高原でキャベツをたくさん栽培している群馬県の村はどこですか。','嬬恋村',['野辺山原','白川村','海津市'],['浅間山のふもとにあります。','日本一のキャベツの産地です。'],'群馬県の嬬恋村は夏のすずしい気候をいかしたキャベツの栽培がさかんです。',{kind:'image', src:'img/diagrams/soc5_landlife_004.webp', alt:'夏の高原に広がるキャベツ畑とレタス畑、遠くに山がある絵', caption:'高原の野菜畑', study:true});
  add('landlife','basic','レタスなどの高原野菜の栽培がさかんな長野県の標高の高い土地は、どこですか。','野辺山原',['嬬恋村','海津市','白川村'],['八ヶ岳のふもとにあります。','標高はおよそ1300mです。'],'長野県の野辺山原は標高が高くすずしい気候でレタスなどの高原野菜の栽培がさかんです。',{kind:'image', src:'img/diagrams/soc5_landlife_004.webp', alt:'夏の高原に広がるキャベツ畑とレタス畑、遠くに山がある絵', caption:'高原の野菜畑', study:true});
  add('landlife','basic','雪の多い北海道などで家の窓にとりつけられる寒さをふせぐ工夫は何ですか。','二重窓',['日よけ','よしず','すだれ'],['窓を二枚にして、間に空気の層をつくります。','部屋の暖かさをにがしません。'],'寒い地方では二重窓などで部屋の暖かさを外ににがさない工夫をしています。',{kind:'image', src:'img/diagrams/soc5_landlife_007.webp', alt:'雪の積もる家の窓が二重になっていて、部屋の中があたたかそうな絵', caption:'二重の窓の雪の家', study:true});
  add('landlife','basic','北海道の札幌で毎年おこなわれる雪や氷の像で人気の行事は、何ですか。','さっぽろ雪まつり',['ねぶた祭','七夕まつり','博多どんたく'],['冬にたくさんの観光客が訪れます。','雪や寒さを生かした行事です。'],'さっぽろ雪まつりは雪や寒さを生かした冬の行事で国内外から観光客が訪れます。',{kind:'image', src:'img/diagrams/soc5_landlife_008.webp', alt:'夜のライトアップされた大きな雪像がならぶまつり。見物の人は小さい', caption:'雪像がならぶ夜のまつり', study:true});
  add('landlife','basic','沖縄県でさかんに栽培されている砂糖の原料になる作物は、何ですか。','サトウキビ',['てんさい','小麦','じゃがいも'],['背の高い草の仲間です。','台風や雨の少ない時期にも強い作物です。'],'沖縄県では暖かい気候をいかして、サトウキビの栽培がさかんです。',{kind:'image', src:'img/diagrams/soc5_landlife_009.webp', alt:'背の高い緑の畑と青い空、遠くに海がある絵', caption:'背の高い緑の畑と海', study:true});

  add('landlife','standard','木曽三川の下流にある海津市などの土地はまわりの川の水面と比べて、どんな特ちょうがありますか。','川の水面より低い土地が多い',['川の水面より高い土地ばかり','山の上にある','雪がたくさん積もる'],['昔から水害がよく起きました。','まわりを堤防でかこむ必要がありました。'],'輪中のある土地は川の水面よりも低く水害を受けやすい土地です。');
  add('landlife','standard','水害がおこったとき、輪中の水をくみ出して、川に流す設備は何ですか。','排水機場',['水力発電所','ダムの水門','じょう水場'],['水を川へ強制的に送りだします。','輪中の水害対策の大切な設備です。'],'排水機場は輪中の水を強制的にくみ出して、川に流す設備で水害をふせぎます。');
  add('landlife','standard','輪中の堤防は何のためにつくられましたか。','水害から家や田畑を守るため',['舟を走らせるため','山を登りやすくするため','観光客を増やすため'],['まわりに川があります。','洪水のとき、水が入ってこないようにします。'],'輪中の堤防は洪水から家や田畑を守るためにつくられました。',{kind:'image', src:'img/diagrams/soc5_landlife_001.webp', alt:'川に囲まれた低い土地を、堤防でぐるりと囲んだ集落と田畑を上から見た絵', caption:'堤防で囲んだ低い土地', study:true});
  add('landlife','standard','標高の高いところで夏にキャベツやレタスをつくるのは、どんな気候を生かしているからですか。','夏でもすずしい気候',['冬でも暖かい気候','一年中暑い気候','雨が少ない気候'],['平地では暑すぎるときです。','高原は夏でも気温が低いです。'],'標高が高い土地は夏でもすずしく暑さに弱い野菜を夏に育てられます。',{kind:'image', src:'img/diagrams/soc5_landlife_004.webp', alt:'夏の高原に広がるキャベツ畑とレタス畑、遠くに山がある絵', caption:'高原の野菜畑', study:true});
  add('landlife','standard','高原野菜の出荷が夏から秋におこなわれるのは、なぜですか。','平地では暑さで野菜がとれにくい時期だから',['平地では雪が積もるから','高原でしか育たないから','夏だけ輸入するから'],['同じ時期に出荷すると、競争になります。','ほかの産地の出荷が少ない時期です。'],'平地の野菜が少なくなる夏に高原で野菜をつくると、よい値段で売れます。',{kind:'image', src:'img/diagrams/soc5_landlife_004.webp', alt:'夏の高原に広がるキャベツ畑とレタス畑、遠くに山がある絵', caption:'高原の野菜畑', study:true});
  add('landlife','standard','野菜の生長をおそくしてふつうの出荷時期よりおくらせて出荷する栽培方法を何といいますか。','抑制栽培',['促成栽培','露地栽培','水耕栽培'],['高原野菜がこの方法です。','「おさえる」という意味の字が使われます。'],'生長をおさえて出荷時期をおくらせる栽培を抑制栽培といいます。',{kind:'image', src:'img/diagrams/soc5_landlife_004.webp', alt:'夏の高原に広がるキャベツ畑とレタス畑、遠くに山がある絵', caption:'高原の野菜畑', study:true});
  add('landlife','standard','雪が多く寒い地方で屋根をかたむけて、雪が自然に落ちるようにするのは、なぜですか。','屋根に雪が積もりすぎるのを防ぐため',['屋根を高く見せるため','雨をためるため','風を通すため'],['雪の重みで家がこわれることがあります。','雪下ろしの手間を減らす工夫です。'],'屋根をかたむけて、雪が自然に落ちるようにして、雪の重みから家を守っています。',{kind:'image', src:'img/diagrams/soc5_landlife_016.webp', alt:'急な傾斜の屋根から雪が落ちている、雪の多い地方の家の絵', caption:'屋根から雪が落ちる家', study:true});
  add('landlife','standard','雪の多い地方で道路にもうけられている雪をとかす装置は何ですか。','ロードヒーティング（融雪装置）',['雪かき機','橋の欄干','信号機'],['道路の下に温水の管や電熱線をうめます。','雪が積もりにくくなります。'],'ロードヒーティングは、道路の下をあたためて、雪をとかす装置です。');
  add('landlife','standard','北海道の根釧台地などでさかんな乳牛を育てて牛乳や乳製品をつくる農業を何といいますか。','酪農',['稲作','果樹栽培','養殖'],['涼しい気候を生かしています。','バターやチーズの原料になります。'],'北海道の根釧台地などでは、涼しい気候を生かした酪農がさかんです。',{kind:'image', src:'img/diagrams/soc5_landlife_018.webp', alt:'広い牧場で乳牛が草を食べ、遠くにサイロがある絵', caption:'乳牛のいる広い牧場', study:true});
  add('landlife','standard','北海道の泥炭地（水はけが悪い土地）を米づくりに使えるように、ほかの土地から土を運んで入れる改良を何といいますか。','客土',['耕地整理','しろかき','直まき'],['土を入れ替えて土地の質を良くします。','石狩平野で行われました。'],'ほかの土地から土を運んで入れて、土地を改良することを客土といいます。');
  add('landlife','standard','沖縄県の伝統的な家に見られる台風の強い風に備える工夫は、何ですか。','屋根のかわらをしっくいで固め石垣で囲む',['屋根を高くする','大きな窓をたくさんつくる','板で屋根をつくる'],['風が強い地域です。','かわらがとばされないようにします。'],'沖縄の伝統的な家はかわらをしっくいで固め石垣で囲むなど台風に備える工夫があります。',{kind:'image', src:'img/diagrams/soc5_landlife_020.webp', alt:'赤いかわら屋根と石垣、屋根の上のシーサーがある伝統的な家の絵', caption:'赤いかわらと石垣の家', study:true});
  add('landlife','standard','沖縄県で水不足に備えて屋根の上や家のそばにおいてある水をためる設備は何ですか。','貯水タンク',['水そう','じょう水池','せき'],['川が短く水がたまりにくい地いきです。','雨水をためて使います。'],'沖縄県では川が短く水不足になりやすいので、貯水タンクで水をためて使います。',{kind:'image', src:'img/diagrams/soc5_landlife_021.webp', alt:'家の屋根の上に白い水がめがあり、青空の絵', caption:'屋根の上の白い水がめ', study:true});
  add('landlife','standard','沖縄県で冬でも暖かい気候を生かしてさかんにつくられている花は何ですか。','菊',['チューリップ','ひまわり','バラだけ'],['お盆やお彼岸に使われる花です。','冬から春に出荷されます。'],'沖縄県では冬でも暖かい気候を生かして、菊などの花づくりがさかんです。');
  add('landlife','standard','沖縄県の産業で人々が多く働いているのは、おもにどんな産業ですか。','観光などのサービス業',['鉄鋼業','林業','製紙業'],['美しい海や自然が人気です。','たくさんの旅行客が訪れます。'],'沖縄県は美しい海や独自の文化を生かした観光業がさかんでサービス業が中心です。');

  add('landlife','standard','野辺山原の標高はおよそ何mですか。','約1300m',['約300m','約3000m','約50m'],['夏でもすずしい気候です。','平地よりずっと高い土地です。'],'野辺山原は標高約1300mの高原で夏でもすずしく高原野菜の栽培がさかんです。');
  add('landlife','advanced','輪中の中には昔水害が起こったとき、舟を家にそなえていたところがあります。その理由は何ですか。','洪水のときの移動や避難に使うため',['魚をとるため','川を渡って買い物にいくため','観光に使うため'],['低い土地は水につかりやすいです。','水屋と合わせてそなえていました。'],'洪水のときの避難や移動に使うため、舟を家にそなえていた輪中の家がありました。',{kind:'image', src:'img/diagrams/soc5_landlife_003.webp', alt:'川ぞいの農家で、高い石垣の上に小さな倉のような建物があり、軒下に小舟がある絵', caption:'石垣の上の倉と軒下の小舟', study:true});
  add('landlife','advanced','海津市の人々がいまも水害にそなえて、取り組んでいることとして、あてはまるものはどれですか。','堤防の整備・排水機場・避難訓練など',['川をうめる','堤防をなくす','水屋を壊す'],['ハードとソフトの両面の対策があります。','県や市が協力して進めています。'],'堤防や排水機場の整備ハザードマップづくりや避難訓練などで水害にそなえています。');
  add('landlife','advanced','嬬恋村で夏にキャベツがたくさんつくられているのは、気候以外にどんな理由がありますか。','広い土地があり大きな市場へ運ぶ交通がととのっているから',['雪が一年中ふるから','海に近いから','森林が少ないから'],['標高の高い土地です。','野菜は運ぶのに時間がかかります。'],'嬬恋村は冷涼な気候と広い畑交通の便を生かして、キャベツの栽培がさかんです。');
  add('landlife','advanced','高い土地で冬にスキーなどのウィンタースポーツを楽しめるのは、どんな気候だからですか。','冬の気温が低く雪がふるから',['冬も暖かいから','雨がたくさんふるから','風がふかないから'],['標高が高い土地は冬は寒いです。','雪の質も良いことがあります。'],'標高が高い土地は冬の気温が低く雪がたくさんふるので、スキー場として、利用されます。',{kind:'image', src:'img/diagrams/soc5_landlife_028.webp', alt:'雪の高原のスキー場。リフトと斜面。スキーヤーはごく小さい', caption:'雪のスキー場', study:true});
  add('landlife','advanced','北海道で寒さに強い稲の品種改良が進んだのは、何のためですか。','寒い地方でも米をつくれるようにするため',['米の輸入を増やすため','雪を減らすため','米をまずくするため'],['稲は暑い土地の植物でした。','気候に合った品種が必要でした。'],'北海道では寒さに強い稲の品種が、品種改良され米づくりがさかんになりました。');
  add('landlife','advanced','北海道の十勝平野や根釧台地で大規模な農業がおこなわれているのは、なぜですか。','広い平らな土地が多いから',['土地がせまいから','山が多いから','雨が少ないから'],['大型の機械が使えます。','北海道の畑はとても広いです。'],'北海道は広い平らな土地が多く大型機械を使った大規模な農業がおこなわれています。', {"kind":"japanMap","bounds":[139.2,41.3,145.9,45.7],"marks":[],"areas":[[[142.8,43.2],[143.45,43.4],[143.85,42.9],[143.4,42.35],[143,42.45]],[[144.6,43.75],[145.3,43.65],[145.5,43.3],[144.75,43.05],[144.45,43.4]]],"routes":[],"lakes":[],"caption":"指定された二つの土地の位置の略図。地名や農業の理由は示していない","study":true});
  add('landlife','advanced','岐阜県の白川郷にある急な角度の屋根をもつ家を何といいますか。','合掌造り',['書院造り','寝殿造り','数寄屋造り'],['世界遺産に登録されています。','雪が多い地方の工夫です。'],'白川郷の合掌造りの家は、急な屋根で雪が積もりにくくなっています。',{kind:'image', src:'img/diagrams/soc5_landlife_031.webp', alt:'雪の山あいの集落に、急な角度の大きな屋根の家々が並ぶ絵', caption:'急な屋根の大きな家々', study:true});
  add('landlife','advanced','高知県や宮崎県が冬でも暖かい気候を生かして、ピーマンやなすなどの出荷をはやめる栽培方法を何といいますか。','促成栽培',['抑制栽培','露地栽培','水耕栽培'],['ビニールハウスなどを使います。','「早める」という意味の字が使われます。'],'冬でも暖かい気候を生かして、野菜の出荷をはやめる栽培方法を促成栽培といいます。',{kind:'image', src:'img/diagrams/soc5_landlife_032.webp', alt:'ビニールハウスの中でピーマンやなすが実り、外は冬の景色の絵', caption:'冬のハウスの中の野菜', study:true});
  add('landlife','advanced','沖縄県で台風の時期にサトウキビがよく育つ理由として、あてはまるものはどれですか。','暑さや雨にも強く風にも強い作物だから',['冷たい水が必要だから','雪の下で育つから','とても弱い作物だから'],['台風が多い地域でも作れる作物です。','サトウキビは昔から栽培されています。'],'サトウキビは暑さや雨に強く台風やかんばつにも強いので、沖縄に向いています。',{kind:'image', src:'img/diagrams/soc5_landlife_009.webp', alt:'背の高い緑の畑と青い空、遠くに海がある絵', caption:'背の高い緑の畑と海', study:true});
  add('landlife','advanced','雪の多い地方では雪をあるものに利用して、環境にやさしい取り組みもおこなわれています。その利用法として、あてはまるものはどれですか。','雪を貯めて夏の冷房に使う',['雪をとかして、道に捨てる','雪をすべて燃やす','雪を山に積み上げて放置する'],['雪の冷たさを利用します。','「雪室」「雪氷冷房」などがあります。'],'雪を貯めておいて、夏の冷房や野菜の保存に利用する取り組みもあります。');
  add('landlife','advanced','暖かい地方と寒い地方では、くらしのどんなところにちがいが見られますか。','家のつくり・農業・祭りなど',['どこも同じ','言葉だけがちがう','服の色だけがちがう'],['気候に合わせた工夫があります。','屋根や窓の形などを思い出しましょう。'],'気候のちがいによって、家のつくり・農業・祭りなどに地いきごとの工夫が見られます。');
  add('landlife','advanced','輪中や高原のくらしの学習から人々のくらしと自然の関係として、いえることはどれですか。','自然の条件に合わせて、工夫して暮らしている',['自然とはまったく関係がない','自然に勝って変えている','自然を無視している'],['気候や地形に合わせた工夫があります。','それぞれの土地のよさを生かしています。'],'人々は地形や気候などの自然条件に合わせて、くらしや産業を工夫しています。');

