  add('rice','basic','日本人がふだんの食事で中心となる食べものとして食べているものを何といいますか。','主食（米）',['副菜','おやつ','調味料'],['ご飯やおにぎりのもとになるものです。','毎日の食事でいちばん多く食べられています。'],'米は日本人の主食でご飯・おもち・せんべいなどさまざまな食品の原料になります。');
  add('rice','basic','米づくりで春に田の土をほり起こしてやわらかくする作業を何といいますか。','田おこし',['しろかき','田植え','稲刈り'],['冬のあいだにかたくなった土をほぐす作業です。','トラクターを使います。'],'田おこしは田の土をほり起こして、やわらかくする作業です。',{kind:'image', src:'img/diagrams/soc5_rice_002.webp', alt:'春の田で、トラクターが土をほり起こしている絵', caption:'田の土をほり起こす', study:true});
  add('rice','basic','米づくりで田に水を入れて土をくだいて平らにならす作業を何といいますか。','しろかき',['田おこし','田植え','稲刈り'],['田植えの前におこなう作業です。','田の水の深さをそろえます。'],'しろかきは田に水を入れて土をくだき平らにならす作業です。',{kind:'image', src:'img/diagrams/soc5_rice_003.webp', alt:'水をはった田をトラクターが平らにならし、水面に空がうつる絵', caption:'水をはった田をならす', study:true});
  add('rice','basic','米づくりで苗を田に植えていく作業を何といいますか。','田植え',['田おこし','稲刈り','もみすり'],['5月ごろにおこなわれます。','いまは田植機を使うことがほとんどです。'],'田植えは育てた苗を田に植える作業で5月ごろにおこなわれます。',{kind:'image', src:'img/diagrams/soc5_rice_004.webp', alt:'水をはった田に、田植機が苗を植えている絵', caption:'苗を植える田', study:true});
  add('rice','basic','秋に実った稲の穂を刈り取る作業を何といいますか。','稲刈り',['田植え','しろかき','田おこし'],['9月から10月ごろです。','コンバインという機械で刈り取ります。'],'稲刈りは秋に実った稲を刈り取る作業です。',{kind:'image', src:'img/diagrams/soc5_rice_005.webp', alt:'秋の黄金色の稲田を、コンバインが刈り取っている絵', caption:'黄金色の稲を刈る', study:true});
  add('rice','basic','稲の実（もみ）からもみがらを取って玄米にする作業を何といいますか。','もみすり',['田おこし','稲刈り','肥料まき'],['稲刈り・脱穀・乾燥のあとの作業です。','玄米をみがくと、白米になります。'],'もみすりはもみがらを取りのぞき玄米にする作業です。',{kind:'image', src:'img/diagrams/soc5_rice_006.webp', alt:'米をととのえる機械と、から、茶色の米がならぶ絵', caption:'からと茶色の米', study:true});
  add('rice','basic','米づくりで田に水を引くために川やダムからつくられた水の通り道を何といいますか。','用水路',['堤防','水田','ため池だけ'],['田に水を運ぶみぞです。','川の水を引いています。'],'用水路は田に水を引くための水路です。',{kind:'image', src:'img/diagrams/soc5_rice_007.webp', alt:'川から引いた水路が、田に水を運んでいる絵', caption:'田へ水を運ぶ水路', study:true});
  add('rice','basic','米づくりに使う稲の種を何といいますか。','種もみ',['玄米','白米','もみがら'],['苗を育てるもとになります。','もみのまままきます。'],'稲の種になるもみを種もみといいます。',{kind:'image', src:'img/diagrams/soc5_rice_008.webp', alt:'もみの入った袋と、苗を育てる箱の絵', caption:'もみの袋と苗の箱', study:true});
  add('rice','basic','米の生産量（収穫量）が、日本でいちばん多い県は、どこですか（2022年）。','新潟県',['北海道','秋田県','山形県'],['日本海側の雪の多い県です。','魚沼のコシヒカリが有名です。'],'米の生産量は新潟県が日本一で北海道・秋田県・山形県が続きます。', {"kind":"japanMap","bounds":[122,24,150,46.7],"marks":[[138.92,37.5]],"areas":[],"routes":[],"lakes":[],"caption":"位置をたしかめるための略地図。地名や数字は示していない","study":true});

  add('rice','standard','米づくりの作業をはやい順にならべたものは、どれですか。','田おこし → しろかき → 田植え → 稲刈り',['稲刈り → 田植え → しろかき → 田おこし','田植え → 田おこし → しろかき → 稲刈り','しろかき → 田おこし → 稲刈り → 田植え'],['春は土づくりから始まります。','最後が収穫です。'],'米づくりは田おこし・しろかき・田植え・稲刈りの順におこなわれます。');
  add('rice','standard','よい種もみを選ぶために塩水に種もみを入れて、しずむものを選ぶ作業を何といいますか。','塩水選',['田おこし','肥料まき','乾燥'],['よい種もみは重くてしずみます。','種もみを選ぶ昔からの知恵です。'],'塩水選は塩水にひたして、しずんだ重い種もみを選ぶ作業です。',{kind:'image', src:'img/diagrams/soc5_rice_011.webp', alt:'塩水を入れたボウルと種もみ。入れる前のようす', caption:'塩水と種もみ', study:true});
  add('rice','standard','田植えはふつう何月ごろにおこなわれますか。','5月',['1月','8月','11月'],['春のおわりごろです。','ゴールデンウィークのころです。'],'田植えは5月ごろにおこなわれます。');
  add('rice','standard','稲刈りはふつう何月ごろにおこなわれますか。','9月から10月',['2月から3月','5月から6月','12月から1月'],['秋に実った稲を収穫します。','「実りの秋」といわれます。'],'稲刈りは9月から10月ごろにおこなわれます。',{kind:'image', src:'img/diagrams/soc5_rice_005.webp', alt:'秋の黄金色の稲田を、コンバインが刈り取っている絵', caption:'黄金色の稲を刈る', study:true});
  add('rice','standard','田植えや稲刈りに使われる機械の組み合わせとして、ただしいものはどれですか。','田植機・コンバイン',['田植機・トラック','コンバイン・ブルドーザー','トラクター・クレーン'],['田植えには田植機が使われます。','稲刈りと脱穀を同時にできる機械があります。'],'田植えは田植機稲刈りと脱穀はコンバインでおこなわれ作業時間がへりました。');
  add('rice','standard','田の形を広く四角く整えて、大型の機械が使いやすくするための工事を何といいますか。','耕地整理（ほ場整備）',['堤防工事','砂防ダムの建設','干拓'],['田の区画を大きくします。','用水路や農道も整えます。'],'耕地整理（ほ場整備）は、田を広く四角く整え大型機械を使いやすくする工事です。',{kind:'image', src:'img/diagrams/soc5_rice_015.webp', alt:'整然と四角く区画された広い田と、まっすぐな農道の絵', caption:'四角く区画された広い田', study:true});
  add('rice','standard','寒さにも強く味がおいしい稲に品種を新しくつくり出すことを何といいますか。','品種改良',['品種選択','肥料改良','土地改良'],['コシヒカリやあきたこまちが有名です。','よい性質をもった稲同士をかけあわせます。'],'より味や育てやすさがよい稲をつくり出すことを品種改良といいます。');
  add('rice','standard','米の産地としてよく知られる秋田県の代表的な品種は、どれですか。','あきたこまち',['コシヒカリ','ひとめぼれ','ゆめぴりか'],['県の名前がついた品種です。','東北地方の米の品種です。'],'あきたこまちは秋田県の代表的な米の品種です。');
  add('rice','standard','米づくりには大量の水が必要です。田に水を送るためにつくられている水をためる設備はどれですか。','ダム・ため池',['送電線','港','高速道路'],['川の水をためておきます。','雨の少ない時期にそなえます。'],'ダムやため池は水をためておき田に必要な水を送ります。',{kind:'image', src:'img/diagrams/soc5_rice_007.webp', alt:'川から引いた水路が、田に水を運んでいる絵', caption:'田へ水を運ぶ水路', study:true});
  add('rice','standard','米の消費量がむかしより減っている理由として、あてはまるものはどれですか。','パンやめんなどを食べることが増えたから',['人口が急に増えたから','米がまずくなったから','米が取れなくなったから'],['食生活が変化してきました。','朝食にパンを食べる人もふえました。'],'食生活が変わりパンやめん肉料理が増えたため、米の消費量がへりました。');
  add('rice','standard','米の生産量がおおすぎないように、田で米以外のものをつくるようにすすめたり作付面積を減らしたりする政策を何といいますか。','生産調整（減反）',['輸入制限','価格自由化','緑化推進'],['米があまりすぎるのをふせぐためです。','2018年に国の配分はなくなりました。'],'米があまるのをふせぐため、生産量を調整する政策がおこなわれてきました（減反）。');
  add('rice','standard','農業をする人（農家）の数が、へってきている理由として、あてはまるものはどれですか。','あとをつぐ人が少なく高齢化が進んでいるから',['農家の収入がとても多いから','仕事がらくだから','土地が余っていないから'],['若い人が少なくなっています。','働いている人の年齢が高くなっています。'],'農家の数はあとつぎ不足や高齢化によって、へりつづけています。');
  add('rice','standard','同じ田で1年のあいだに米と麦のように、二種類の作物を順番につくることを何といいますか。','二毛作',['二期作','二重作','輪作'],['冬に麦をつくり夏に米をつくる例があります。','土地をむだなく使う方法です。'],'同じ田畑で1年に2種類の作物を順にそだてる方法を二毛作といいます。');
  add('rice','standard','米をつくるのに適した広い平らな土地と水が得られる地いきとして、あてはまるものはどれですか。','東北地方や北陸の平野',['砂漠','山のいただき','北極圏'],['大きな川が流れています。','雪どけ水が得られる土地です。'],'広い平野と豊かな水がある東北や北陸の平野は、米づくりがさかんです。');
